CREATE TABLE IF NOT EXISTS video_privacy_governance_profiles(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,camera_id TEXT,purpose TEXT NOT NULL CHECK(length(trim(purpose))>0),consent_basis TEXT NOT NULL CHECK(length(trim(consent_basis))>0),signage_status TEXT NOT NULL CHECK(length(trim(signage_status))>0),retention_days INTEGER NOT NULL CHECK(retention_days BETWEEN 1 AND 90),access_review_due_at TEXT NOT NULL,non_biometric_alternative TEXT NOT NULL CHECK(length(trim(non_biometric_alternative))>0),legal_hold_policy TEXT NOT NULL,export_policy TEXT NOT NULL,deletion_policy TEXT NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS video_pilot_certification_runs(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,status TEXT NOT NULL,provider_mode TEXT NOT NULL,total_checks INTEGER NOT NULL,passed_checks INTEGER NOT NULL,stream_evidence_json TEXT NOT NULL,model_metrics_json TEXT NOT NULL,governance_json TEXT NOT NULL,recovery_evidence_json TEXT NOT NULL,production_enabled INTEGER NOT NULL DEFAULT 0,real_camera_connected INTEGER NOT NULL DEFAULT 0,real_payment_captured INTEGER NOT NULL DEFAULT 0,real_credential_issued INTEGER NOT NULL DEFAULT 0,executed_by TEXT NOT NULL,executed_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS express_checkin_compensation_events(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,session_id TEXT NOT NULL,scenario TEXT NOT NULL,event_type TEXT NOT NULL,idempotency_key TEXT NOT NULL,status TEXT NOT NULL,evidence_json TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(organization_id,property_id,idempotency_key,event_type));
CREATE INDEX IF NOT EXISTS video_governance_review_idx ON video_privacy_governance_profiles(organization_id,property_id,access_review_due_at);
CREATE INDEX IF NOT EXISTS video_pilot_history_idx ON video_pilot_certification_runs(organization_id,property_id,executed_at);
CREATE INDEX IF NOT EXISTS checkin_compensation_scope_idx ON express_checkin_compensation_events(organization_id,property_id,session_id,created_at);
